function addTree(x,z,scale=1,kind=0){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);city.add(g);cyl(g,0,1.2,0,.24,.31,2.4,mTrunk,8);const leaf=kind===1?mLeaf2:mLeaf;for(let i=0;i<4;i++){const r=kind===2?.8-i*.11:1.04-i*.16,y=2.15+i*.48;const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(r,1),leaf);crown.position.set((rand()-.5)*.24,y,(rand()-.5)*.2);crown.castShadow=true;crown.receiveShadow=true;g.add(crown)}return g}
function addRoad(x,z,w,d,rotation=0){const road=meshBox(city,x,.035,z,w,.08,d,mRoad,false,true);road.rotation.y=rotation;const curbOffset=rotation===0?d/2:w/2;for(const side of [-1,1]){const curb=meshBox(city,x+(rotation===0?0:side*curbOffset),.1,z+(rotation===0?side*curbOffset:0),rotation===0?w:d,.18,.28,mCurb,false,true);curb.rotation.y=rotation}
