}
function addBuilding(x,z,w,d,h,seed){const r=seeded(seed);const g=new THREE.Group();g.position.set(x,0,z);city.add(g);const pal=['#c6b7a0','#b6c1b6','#d1c9b8','#887f72','#9ca8a3','#d5d0c0','#adab9c'];const shell=mat(pal[Math.floor(r()*pal.length)],.83);meshBox(g,0,h/2,0,w,h,d,shell);meshBox(g,0,h+.16,0,w+.28,.32,d+.28,mRoof);meshBox(g,0,.18,d/2+.03,w,.36,.15,mat('#65665d'),false,true);
