 const bridge=meshBox(city,52,.35,18,18,.5,4.5,mat('#9c8866'));for(const s of [-1,1])meshBox(city,52,.8,18+s*2.1,18,.12,.14,mWood);
 // downtown towers and neighborhood storefronts
 for(let i=0;i<16;i++){const x=-57+i*7.6,z=-46-(i%3)*7,w=5.1+(i%3)*.65,d=5.6+(i%2),h=10+(i%5)*3.2;addBuilding(x,z,w,d,h,741+i*33)}
 for(let i=0;i<9;i++){const z=-40-i*7.5;addBuilding(-75,z,7,7,15+(i%3)*4,1500+i*19);addBuilding(75,z,7.5,7,18+(i%4)*3,1900+i*21)}
 for(let i=0;i<8;i++){const x=-28+i*8;addBuilding(x,-26-(i%2)*2,6.6,6.3,7+(i%3)*1.3,2500+i*31)}
