 const px=-11,pz=20;for(const [x,z] of [[px-3,pz-3],[px+3,pz-3],[px-3,pz+3],[px+3,pz+3]])cyl(city,x,1.8,z,.12,.12,3.6,mat('#816a4e'),8);meshBox(city,px,3.72,pz,7,.28,7,mat('#887657'));meshBox(city,px,.11,pz,7,.18,7,mat('#b8a782'),false,true);
