function makeSwatch(item){let icon='';if(item.type==='log')icon='◉';else if(item.type==='door')icon='▯';else if(item.type==='fence'||item.type==='stoneFence')icon='▥';else if(item.type==='slab'||item.type==='thinSlab'||item.type==='patternSlab')icon='▬';else if(item.type==='led')icon=item.shape==='stick'?'╎':item.shape==='plate'?'▰':'●';else if(item.type==='lamp'||item.type==='bulb')icon='✦';else if(item.type==='glassPane')icon='▯';else if(item.type==='prop')icon='◇';else icon='▦';return icon}
