function selectItem(item){selected=item;document.querySelector('#selectedName').textContent=item.name;document.querySelector('#selectedHint').textContent=item.type==='prop'?'Display model · non-combat':'Unlimited · ready to place';document.querySelector('#equipBtn').disabled=false;document.querySelector('#equipBtn').textContent='EQUIP';document.querySelector('#chipName').textContent=item.name;document.querySelector('.chip-swatch').style.background=item.color;document.querySelector('#selectedChip').classList.add('visible');renderItems();say(`${item.name} selected`)}
