const gridSize=1.5;let rotation=0;function snap(n){return Math.round(n/gridSize)*gridSize}
function makePlaceable(item,pos,rot=0,save=true){const g=new THREE.Group();g.position.set(snap(pos.x),Math.max(0,pos.y),snap(pos.z));g.rotation.y=rot;const material=createMaterial(item),dark=mat(new THREE.Color(item.color).multiplyScalar(.67)),edge=mat('#e9e3d3',.57),type=item.type;const box=(x,y,z,sx,sy,sz,m=material)=>meshBox(g,x,y,z,sx,sy,sz,m);const center=gridSize/2;
 if(type==='log'){const log=cyl(g,center,.52,center,.37,.37,1.34,material,12);log.rotation.z=Math.PI/2;for(const x of [.05,1.29]){const cap=cyl(g,x,.52,center,.34,.34,.035,edge,12);cap.rotation.z=Math.PI/2;for(let r=.11;r<.31;r+=.1){const ring=new THREE.Mesh(new THREE.TorusGeometry(r,.012,4,16),dark);ring.position.set(x+(x<.5?-.025:.025),.52,center);ring.rotation.y=Math.PI/2;g.add(ring)}}}
 else if(type==='wall'){box(center,.76,center,1.5,1.48,.13);for(let y=.12;y<1.5;y+=.37)box(center,y,center-.08,1.5,.025,.02,dark)}
 else if(type==='fence'||type==='stoneFence'){const tall=type==='stoneFence'?1.5:1.28;for(const x of [.15,1.35])box(x,tall/2,center,.22,tall,.22,type==='stoneFence'?material:dark);box(center,.28,center,1.5,.16,.17,material);box(center,tall-.22,center,1.5,.2,.17,material);if(type==='fence'){for(const x of [.42,.72,1.02])box(x,tall/2,center,.09,tall-.28,.12,material)}else{for(let x=.3;x<1.4;x+=.27)box(x,tall/2,center,.25,tall,.22,material)}}
 else if(type==='door'){box(center,1,center,1.02,2,.15,material);box(center,1,center-.09,.06,1.7,.04,dark);for(const x of [.34,.75,1.16])box(x,1,center-.105,.035,1.75,.025,edge);const knob=new THREE.Mesh(new THREE.SphereGeometry(.055,8,8),edge);knob.position.set(1.02,1,center-.14);g.add(knob)}
 else if(type==='slab'||type==='thinSlab'||type==='patternSlab'){const h=type==='thinSlab'||type==='patternSlab'?.18:.46;box(center,h/2,center,1.5,h,1.5,material);if(item.pattern){for(let i=0;i<5;i++){const vein=box(.18+i*.28,h+.008,center,.03,.012,1.24,i%2?edge:dark);vein.rotation.y=(i-2)*.08}}}
