 else if(type==='glassBlock'||type==='glassPane'){const width=type==='glassPane'?1.5:1.4,depth=type==='glassPane'?.09:1.3;const pane=box(center,.75,center,width,1.5,depth,material);pane.material.side=THREE.DoubleSide;if(type==='glassBlock'){box(center,.75,center,1.42,.045,1.32,edge).material.transparent=true;box(center,.75,center,.045,1.42,1.32,edge).material.transparent=true}else{box(center,.75,center-.055,1.56,.055,.12,dark);box(center,.75,center+.055,1.56,.055,.12,dark)}}
