.inventory-toggle small{font-size:8px;color:#9daaa0;border-left:1px solid #ffffff30;padding-left:9px}
.inventory-toggle kbd{font:10px 'DM Sans';margin-left:7px;padding:4px 6px;border:1px solid #ffffff35;border-radius:5px;color:#bac4b7}
