content.text:
.inventory-toggle{position:absolute;z-index:4;bottom:24px;left:29px;height:54px;padding:0 14px;display:flex;align-items:center;gap:10px;border:1px solid #ffffff40;border-radius:13px;background:rgba(20,37,30,.88);color:#f7f3e8;box-shadow:0 8px 30px #17251c35;cursor:pointer}
.inventory-toggle>span{font-size:20px;color:#d7e5b5}
.inventory-toggle b{font-size:10px;letter-spacing:1.1px}
.inventory-toggle small{font-size:8px;color:#9daaa0;border-left:1px solid #ffffff30;padding-left:9px}
.inventory-toggle kbd{font:10px 'DM Sans';margin-left:7px;padding:4px 6px;border:1px solid #ffffff35;border-radius:5px;color:#bac4b7}
.inventory{position:absolute;z-index:6;left:24px;top:50%;transform:translate(-115%,-50%);width:min(410px,calc(100vw - 32px));height:min(690px,calc(100vh - 112px));padding:20px;background:rgba(246,246,236,.97);color:#24332d;border:1px solid #fff;border-radius:19px;box-shadow:0 20px 70px #11241b50;display:flex;flex-direction:column;transition:transform .35s cubic-bezier(.22,.8,.25,1);backdrop-filter:blur(22px)}
.selected-chip{position:absolute;right:28px;bottom:24px;z-index:3;display:flex;align-items:center;gap:10px;padding:9px 11px;background:rgba(246,246,236,.94);color:#2e4036;border:1px solid white;border-radius:12px;box-shadow:0 8px 25px #11241b30;min-width:170px}
.selected-chip small{display:block;color:#819082;font-size:7px;letter-spacing:1px;margin-bottom:2px}
.selected-chip b{font-size:10px}
.selected-chip button{margin-left:auto;border:0;background:#e6ecd9;color:#58744c;width:27px;height:27px;border-radius:7px;font-size:17px;cursor:pointer}
.touch-controls{display:none}
@media(max-width:700px){.topbar{height:64px;padding:0 14px}
.inventory{left:8px;width:calc(100vw - 16px);height:min(67vh,590px);top:auto;bottom:8px;transform:translateY(120%);padding:14px;border-radius:17px}
.inventory-toggle{left:12px;bottom:13px;height:48px;padding:0 11px}
.inventory-toggle small,.inventory-toggle kbd{display:none}
.selected-chip{right:12px;bottom:13px;min-width:145px;padding:7px}
.touch-controls{display:block}
.inventory.open~.inventory-toggle,.inventory.open~.selected-chip{display:none}
@media(min-width:701px) and (max-height:650px){.inventory{height:calc(100vh - 90px);padding:14px}

